#!/usr/bin/env node
/**
 * Generates the contact guard's two detectors from one spec.
 *
 *   design/contact-guard.spec.mjs      rules, pipeline, lexicons (hand-written)
 *   design/contact-guard.tables.json   Unicode tables (generated by --tables)
 *     -> supabase/migrations/<MIGRATION>          PL/pgSQL, schema private (the server decides)
 *     -> src/lib/contactGuard.generated.ts        TypeScript mirror, hard tier only (the app predicts)
 *
 * Usage:
 *   node scripts/gen-contact-guard.mjs            write both outputs
 *   node scripts/gen-contact-guard.mjs --check    fail if either output is stale (RULE 4)
 *   node scripts/gen-contact-guard.mjs --tables   rebuild the Unicode tables from this Node's ICU
 *
 * The tables are committed rather than rebuilt on every run so the output does
 * not change with the Node version that happens to run the generator: a
 * different ICU would silently move the fold table under a deployed migration.
 *
 * Both outputs are driven by the same op list, and `supabase/tests/
 * contact_guard_cases.json` is asserted against both (Jest for the mirror,
 * pgTAP through scripts/db-test.mjs for the SQL), so they cannot drift.
 */
import { createHash } from 'node:crypto';
import { readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = fileURLToPath(new URL('..', import.meta.url));
const SPEC_PATH = join(ROOT, 'design/contact-guard.spec.mjs');
const TABLES_PATH = join(ROOT, 'design/contact-guard.tables.json');
const TS_PATH = join(ROOT, 'src/lib/contactGuard.generated.ts');
const CHECK = process.argv.includes('--check');
const TABLES = process.argv.includes('--tables');
const LABEL = CHECK ? 'contact-guard:check' : 'contact-guard';

const spec = await import(SPEC_PATH);

// ---------------------------------------------------------------------------
// Unicode tables
// ---------------------------------------------------------------------------

function ranges(predicate) {
  const out = [];
  let start = -1;
  for (let cp = 0; cp <= 0x10ffff + 1; cp += 1) {
    const inside =
      cp <= 0x10ffff && !(cp >= 0xd800 && cp <= 0xdfff) && predicate(cp);
    if (inside && start < 0) {
      start = cp;
    } else if (!inside && start >= 0) {
      out.push([start, cp - 1]);
      start = -1;
    }
  }
  return out;
}

function buildTables() {
  const nd = /^\p{Nd}$/u;
  const mark = /^[\p{Mn}\p{Me}]$/u;
  const invisible = /^[\p{Cf}]$/u;
  const fold = new Map();
  for (let cp = 0x80; cp <= 0x1ffff; cp += 1) {
    if (cp >= 0xd800 && cp <= 0xdfff) {
      continue;
    }
    const ch = String.fromCodePoint(cp);
    if (nd.test(ch)) {
      let start = cp;
      while (start > 0 && nd.test(String.fromCodePoint(start - 1))) {
        start -= 1;
      }
      fold.set(cp, String((cp - start) % 10));
      continue;
    }
    const base = ch
      .normalize('NFKD')
      .replace(/\p{M}/gu, '')
      .replace(/[A-Z]/g, c => c.toLowerCase());
    if (base.length === 1 && /^[a-z0-9@.+#_:/-]$/.test(base)) {
      fold.set(cp, base);
    }
  }
  for (const [from, to] of Object.entries(spec.CONFUSABLES)) {
    const cp = from.codePointAt(0);
    if (cp < 0x80) {
      throw new Error(`CONFUSABLES maps an ASCII character: ${from}`);
    }
    if (!fold.has(cp)) {
      fold.set(cp, to);
    }
  }
  const sorted = [...fold.entries()].sort((a, b) => a[0] - b[0]);
  return {
    source: `Node ${process.versions.node}, ICU ${process.versions.icu}, Unicode ${process.versions.unicode}`,
    fold: {
      from: sorted.map(([cp]) => String.fromCodePoint(cp)).join(''),
      to: sorted.map(([, to]) => to).join(''),
    },
    marks: ranges(cp => mark.test(String.fromCodePoint(cp))),
    invisible: [
      ...ranges(cp => invisible.test(String.fromCodePoint(cp))),
      [0x115f, 0x1160],
      [0x2800, 0x2800],
      [0x3164, 0x3164],
      [0xfe00, 0xfe0f],
      [0xffa0, 0xffa0],
    ].sort((a, b) => a[0] - b[0]),
  };
}

if (TABLES) {
  writeFileSync(TABLES_PATH, `${JSON.stringify(buildTables(), null, 1)}\n`);
  console.log(`contact-guard: tables written -> ${TABLES_PATH}`);
  process.exit(0);
}

const tables = JSON.parse(readFileSync(TABLES_PATH, 'utf8'));

// ---------------------------------------------------------------------------
// Dialect: one pattern string, two engines
// ---------------------------------------------------------------------------

const hex4 = n => n.toString(16).padStart(4, '0');
const hex8 = n => n.toString(16).padStart(8, '0');
/** A code point as a spec escape: \uXXXX in the BMP, \UXXXXXXXX above it. */
const esc = cp => (cp <= 0xffff ? `\\u${hex4(cp)}` : `\\U${hex8(cp)}`);
const classOf = rs =>
  rs.map(([a, b]) => (a === b ? esc(a) : `${esc(a)}-${esc(b)}`)).join('');

const MARKS = classOf(tables.marks);
const INVISIBLE = classOf(tables.invisible);
const SPACES = String.raw`\u0009-\u000d\u0085\u00a0\u1680\u2000-\u200a\u2028\u2029\u202f\u205f\u3000`;

/** Forbidden constructs, the list the spec's header states. */
const FORBIDDEN = [
  [/(^|[^\\])\\[dwsbDWSB]/, 'a \\d \\w \\s or \\b class'],
  [/(^|[^\\[])\.(?![^[]*\])/, 'an unescaped "."'],
  [/[*+?}]\?/, 'a lazy quantifier'],
  [/\\[1-9]/, 'a back-reference'],
  [/\{\d+,?(\d{4,}|[3-9]\d{2}|2[6-9]\d|25[6-9])\}/, 'a bound above 255'],
];

export function lintPattern(re) {
  const problems = [];
  // Strip character classes before the "." check, where a dot is literal.
  const outside = re.replace(/\[(?:\\.|[^\]\\])*\]/g, '[]');
  for (const [pattern, what] of FORBIDDEN) {
    const target = what.includes('"."') ? outside : re;
    if (pattern.test(target)) {
      problems.push(what);
    }
  }
  return problems;
}

/** A spec pattern as JavaScript RegExp source (with the u flag). */
/** A value as TypeScript source with every non-ASCII code unit escaped, so no raw glyph (an em dash in the fold table) reaches the file. */
const jsStr = v =>
  JSON.stringify(v).replace(
    /[\u007f-\uffff]/g,
    c => `\\u${c.charCodeAt(0).toString(16).padStart(4, '0')}`,
  );
const toJs = re =>
  re.replace(
    /\\U([0-9a-fA-F]{8})/g,
    (_, h) => `\\u{${parseInt(h, 16).toString(16)}}`,
  );
/** A string as a SQL literal. standard_conforming_strings is on: backslashes are literal. */
const sqlLit = s => `'${s.replace(/'/g, "''")}'`;
/** A spec replacement ($1) as Postgres's (\1). */
const toPgReplacement = to => to.replace(/\$(\d)/g, '\\$1');

// ---------------------------------------------------------------------------
// Ops
// ---------------------------------------------------------------------------

const NON_ASCII = String.raw`[^\u0001-\u007f]`;

/** Every op, as a SQL statement on `v` and a JS expression on `v`. */
function emitOp(op, ctx) {
  switch (op.op) {
    case 'strip_invisible':
      return {
        sql: `if v ~ ${sqlLit(NON_ASCII)} then v := regexp_replace(v, ${sqlLit(
          `[${INVISIBLE}]+`,
        )}, '', 'g'); end if;`,
        js: `v = hasNonAscii(v) ? v.replace(${ctx.re(
          `[${INVISIBLE}]+`,
          'gu',
        )}, '') : v;`,
      };
    case 'fold':
      return {
        sql: `if v ~ ${sqlLit(NON_ASCII)} then v := translate(v, ${sqlLit(
          tables.fold.from,
        )}, ${sqlLit(tables.fold.to)}); end if;`,
        js: `v = hasNonAscii(v) ? translate(v, foldMap()) : v;`,
      };
    case 'lower':
      return {
        sql: `v := translate(v, 'ABCDEFGHIJKLMNOPQRSTUVWXYZ', 'abcdefghijklmnopqrstuvwxyz');`,
        js: `v = v.replace(/[A-Z]/g, c => c.toLowerCase());`,
      };
    case 'strip_marks_after_ascii':
      return {
        sql: `if v ~ ${sqlLit(
          NON_ASCII,
        )} then v := regexp_replace(regexp_replace(v, ${sqlLit(
          `^[${MARKS}]+`,
        )}, ''), ${sqlLit(
          `([\\u0001-\\u007f])[${MARKS}]+`,
        )}, '\\1', 'g'); end if;`,
        js: `v = hasNonAscii(v) ? v.replace(${ctx.re(
          `^[${MARKS}]+`,
          'u',
        )}, '').replace(${ctx.re(
          `([\\u0001-\\u007f])[${MARKS}]+`,
          'gu',
        )}, '$1') : v;`,
      };
    case 'spaces':
      return {
        sql: `v := regexp_replace(v, ${sqlLit(`[${SPACES}]`)}, ' ', 'g');`,
        js: `v = v.replace(${ctx.re(`[${SPACES}]`, 'gu')}, ' ');`,
      };
    case 'replace':
      return {
        sql: `v := regexp_replace(v, ${sqlLit(op.re)}, ${sqlLit(
          toPgReplacement(op.to),
        )}, 'g');`,
        js: `v = v.replace(${ctx.re(op.re, 'gu')}, ${JSON.stringify(op.to)});`,
      };
    case 'reverse':
      return {
        sql: 'v := reverse(v);',
        js: `v = Array.from(v).reverse().join('');`,
      };
    case 'tokens': {
      const cls = op.match;
      const split = `([${cls}]+|[^${cls}]+)`;
      const isToken = `^[${cls}]`;
      let sqlMap;
      let jsMap;
      if (op.dict !== undefined) {
        const name = ctx.dict(op.dict);
        sqlMap = `coalesce(${sqlLit(
          JSON.stringify(op.dict),
        )}::jsonb ->> r.m[1], r.m[1])`;
        jsMap = `(${name}().get(tok) ?? tok)`;
      } else {
        const tmap = ctx.tmap(op.translate.from, op.translate.to);
        sqlMap = `case when r.m[1] ~ ${sqlLit(
          op.when,
        )} then translate(r.m[1], ${sqlLit(op.translate.from)}, ${sqlLit(
          op.translate.to,
        )}) else r.m[1] end`;
        jsMap = `(${ctx.re(
          op.when,
          'u',
        )}.test(tok) ? translate(tok, ${tmap}) : tok)`;
      }
      const guardSql =
        op.guard !== undefined ? `if v ~ ${sqlLit(op.guard)} then ` : '';
      const guardEnd = op.guard !== undefined ? ' end if;' : '';
      const guardJs =
        op.guard !== undefined ? `${ctx.re(op.guard, 'u')}.test(v) ? ` : '';
      const guardJsEnd = op.guard !== undefined ? ' : v' : '';
      return {
        sql:
          `${guardSql}v := coalesce((select string_agg(case when r.m[1] ~ ${sqlLit(
            isToken,
          )} then ${sqlMap} else r.m[1] end, '' order by r.o) ` +
          `from regexp_matches(v, ${sqlLit(
            split,
          )}, 'g') with ordinality as r(m, o)), '');${guardEnd}`,
        js: `v = ${guardJs}v.replace(${ctx.re(
          `[${cls}]+`,
          'gu',
        )}, tok => ${jsMap})${guardJsEnd};`,
      };
    }
    default:
      throw new Error(`unknown op ${op.op}`);
  }
}

// ---------------------------------------------------------------------------
// Emit
// ---------------------------------------------------------------------------

const COPY_NAMES = spec.COPIES.map(c => c.name);
const hardByCopy = name =>
  spec.HARD.filter(r => r.copy === name && r.requires === undefined);
const combined = rules => rules.map(r => `(?:${r.re})`).join('|');
const HARD_IDS = [...new Set(spec.HARD.map(r => r.id))];
const CATEGORY_OF = Object.fromEntries(spec.HARD.map(r => [r.id, r.category]));
const PHONE_IDS = HARD_IDS.filter(id => CATEGORY_OF[id] === 'phone');

// Lint every pattern before emitting anything.
const allPatterns = [
  ...spec.COPIES.flatMap(c =>
    c.steps
      .filter(s => s.op === 'replace')
      .map(s => [`${c.name}: ${s.re}`, s.re]),
  ),
  ...spec.COPIES.flatMap(c =>
    c.steps
      .filter(s => s.op === 'tokens' && s.when)
      .map(s => [`${c.name}.when`, s.when]),
  ),
  ...spec.HARD.map(r => [r.id, r.re]),
  ...spec.HARD.filter(r => r.requires).map(r => [
    `${r.id}.requires`,
    r.requires.re,
  ]),
  ...spec.SIGNAL.map(r => [r.id, r.re]),
  ...spec.SIGNAL.filter(r => r.unless).map(r => [
    `${r.id}.unless`,
    r.unless.re,
  ]),
  ...spec.FRAGMENT.steps.map(s => ['fragment', s.re]),
  ['fragment.shape', spec.FRAGMENT.shape],
  ['fragment.mobile', spec.FRAGMENT.mobile],
  ['fragment.chatter', spec.FRAGMENT.chatter],
  ['prefilter', spec.PREFILTER.re],
];
for (const [where, re] of allPatterns) {
  const problems = lintPattern(re);
  if (problems.length > 0) {
    console.error(`${LABEL} FAILED: ${where} uses ${problems.join(', ')}`);
    process.exit(1);
  }
  RegExp(toJs(re), 'u'); // throws on a pattern JavaScript rejects
}
for (const rule of [...spec.HARD, ...spec.SIGNAL]) {
  for (const copy of [rule.copy, rule.requires?.copy, rule.unless?.copy].filter(
    Boolean,
  )) {
    if (!COPY_NAMES.includes(copy)) {
      console.error(
        `${LABEL} FAILED: rule ${rule.id} reads unknown copy ${copy}`,
      );
      process.exit(1);
    }
  }
}

// The spec version: a hash of everything that decides a verdict.
const SPEC_SHA = createHash('sha256')
  .update(
    JSON.stringify({
      copies: spec.COPIES,
      hard: spec.HARD,
      signal: spec.SIGNAL,
      fragment: spec.FRAGMENT,
      prefilter: spec.PREFILTER,
      categories: spec.CATEGORY_ORDER,
      tables,
    }),
  )
  .digest('hex');

// --- JS context: hoisted regexes and maps ----------------------------------
const jsRegexes = [];
const jsDicts = [];
const jsTmaps = [];
const jsCtx = {
  re(source, flags) {
    const key = `${flags}:${source}`;
    let index = jsRegexes.findIndex(r => r.key === key);
    if (index < 0) {
      index = jsRegexes.length;
      jsRegexes.push({ key, source: toJs(source), flags });
    }
    return `re(${index})`;
  },
  dict(dict) {
    let index = jsDicts.indexOf(dict);
    if (index < 0) {
      index = jsDicts.length;
      jsDicts.push(dict);
    }
    return `dict${index}`;
  },
  tmap(from, to) {
    let index = jsTmaps.findIndex(t => t.from === from && t.to === to);
    if (index < 0) {
      index = jsTmaps.length;
      jsTmaps.push({ from, to });
    }
    return `tmap${index}()`;
  },
};

function copyChain(name) {
  const copy = spec.COPIES.find(c => c.name === name);
  return copy;
}

// --- SQL --------------------------------------------------------------------
const sqlCopyFns = spec.COPIES.map(copy => {
  const body = copy.steps
    .map(step => `  ${emitOp(step, jsCtx).sql}`)
    .join('\n');
  return `create or replace function private.cg_copy_${copy.name}(p text)
returns text
language plpgsql
immutable
strict
parallel safe
as $fn$
declare
  v text := p;
begin
${body}
  return v;
end;
$fn$;`;
});

const sqlArg = copy => (copy.from === 'input' ? 'p_text' : `v_${copy.from}`);
const sqlDeclareCopies = COPY_NAMES.map(n => `  v_${n} text;`).join('\n');
const sqlAllCopies = spec.COPIES.map(
  c => `  v_${c.name} := private.cg_copy_${c.name}(${sqlArg(c)});`,
).join('\n');

const sqlBlockedBody = [];
sqlBlockedBody.push(`  v_t := private.cg_copy_t(p_text);`);
sqlBlockedBody.push(
  `  if v_t !~ ${sqlLit(spec.PREFILTER.re)} then\n    return false;\n  end if;`,
);
for (const copy of spec.COPIES) {
  if (copy.name !== 't') {
    sqlBlockedBody.push(
      `  v_${copy.name} := private.cg_copy_${copy.name}(${sqlArg(copy)});`,
    );
  }
  const rules = hardByCopy(copy.name);
  if (rules.length > 0) {
    sqlBlockedBody.push(
      `  if v_${copy.name} ~ ${sqlLit(
        combined(rules),
      )} then\n    return true;\n  end if;`,
    );
  }
}
for (const rule of spec.HARD.filter(r => r.requires)) {
  sqlBlockedBody.push(
    `  if v_${rule.copy} ~ ${sqlLit(rule.re)} and v_${
      rule.requires.copy
    } ~ ${sqlLit(rule.requires.re)} then\n    return true;\n  end if;`,
  );
}

const sqlRuleTests = spec.HARD.map(rule => {
  const cond = rule.requires
    ? `v_${rule.copy} ~ ${sqlLit(rule.re)} and v_${
        rule.requires.copy
      } ~ ${sqlLit(rule.requires.re)}`
    : `v_${rule.copy} ~ ${sqlLit(rule.re)}`;
  return `  if not (${sqlLit(
    rule.id,
  )} = any(v_ids)) and ${cond} then\n    v_ids := v_ids || ${sqlLit(
    rule.id,
  )}::text;\n  end if;`;
}).join('\n');

const sqlSignalTests = spec.SIGNAL.map(rule => {
  const cond = rule.unless
    ? `v_${rule.copy} ~ ${sqlLit(rule.re)} and v_${
        rule.unless.copy
      } !~ ${sqlLit(rule.unless.re)}`
    : `v_${rule.copy} ~ ${sqlLit(rule.re)}`;
  return `  if not (${sqlLit(
    rule.id,
  )} = any(v_ids)) and ${cond} then\n    v_ids := v_ids || ${sqlLit(
    rule.id,
  )}::text;\n  end if;`;
}).join('\n');
const SIGNAL_COPIES = [
  ...new Set(
    spec.SIGNAL.flatMap(r => [r.copy, r.unless?.copy].filter(Boolean)),
  ),
];
for (const copy of SIGNAL_COPIES) {
  if (copy !== 't') {
    throw new Error('signal rules may only read copy t');
  }
}

const fragmentSteps = spec.FRAGMENT.steps
  .map(step => `  ${emitOp(step, jsCtx).sql}`)
  .join('\n');
const phoneCopyPath = [];
{
  let c = copyChain(spec.FRAGMENT.copy);
  while (c) {
    phoneCopyPath.unshift(c);
    c = c.from === 'input' ? null : copyChain(c.from);
  }
}
const sqlFragmentCopies = phoneCopyPath
  .map(
    c =>
      `  v := private.cg_copy_${c.name}(${
        c.from === 'input' ? 'p_text' : 'v'
      });`,
  )
  .join('\n');

const categoryCase = spec.CATEGORY_ORDER.map(cat => {
  const ids = HARD_IDS.filter(id => CATEGORY_OF[id] === cat);
  return `    when p_rules && array[${ids
    .map(sqlLit)
    .join(', ')}]::text[] then ${sqlLit(cat)}`;
}).join('\n');

const header = `-- ===========================================================================
-- GENERATED by scripts/gen-contact-guard.mjs from design/contact-guard.spec.mjs
-- and design/contact-guard.tables.json. DO NOT EDIT: edit the spec and run
-- \`npm run contact-guard\`. \`npm run contact-guard:check\` fails on drift.
-- spec_sha256: ${SPEC_SHA}
-- ===========================================================================
-- The contact guard's detector, the server half. The app ships a TypeScript
-- mirror of the hard tier generated from the same spec; the same fixture
-- (supabase/tests/contact_guard_cases.json) is asserted against both.
--
-- Everything is in schema private (127), which PostgREST does not expose, and
-- revoked from every client role: the gate in 157 calls these as its owner.
-- Nothing here is secret (the APK carries the hard rules), but a detector a
-- client can call is a free way to spend database CPU on arbitrary text.
--
-- The functions are pure: immutable, strict, parallel safe. They read no
-- table and no setting, so a verdict depends only on the text and the spec.
-- Postgres regular expressions (ARE):
-- https://www.postgresql.org/docs/current/functions-matching.html#POSIX-SYNTAX-DETAILS
`;

const sql = `${header}
${sqlCopyFns.join('\n\n')}

-- True when any hard rule fires. The write path's only detector call.
create or replace function private.contact_guard_blocked(p_text text)
returns boolean
language plpgsql
immutable
strict
parallel safe
as $fn$
declare
${sqlDeclareCopies}
begin
${sqlBlockedBody.join('\n')}
  return false;
end;
$fn$;

-- The hard rule ids that fire, in spec order. Called after a hit, for the
-- category, the reason and the event row.
create or replace function private.contact_guard_rules(p_text text)
returns text[]
language plpgsql
immutable
strict
parallel safe
as $fn$
declare
${sqlDeclareCopies}
  v_ids text[] := '{}';
begin
  v_t := private.cg_copy_t(p_text);
  if v_t !~ ${sqlLit(spec.PREFILTER.re)} then
    return v_ids;
  end if;
${sqlAllCopies.split('\n').slice(1).join('\n')}
${sqlRuleTests}
  return v_ids;
end;
$fn$;

-- The signal rule ids that fire: intent with no identifier. Logged for
-- review and never blocked. Server only; the mirror does not carry these.
create or replace function private.contact_guard_signals(p_text text)
returns text[]
language plpgsql
immutable
strict
parallel safe
as $fn$
declare
  v_t text;
  v_ids text[] := '{}';
begin
  v_t := private.cg_copy_t(p_text);
${sqlSignalTests}
  return v_ids;
end;
$fn$;

-- The category the UI names, by priority. Null when no hard rule fired.
create or replace function private.contact_guard_category(p_rules text[])
returns text
language sql
immutable
strict
parallel safe
as $fn$
  select case
${categoryCase}
  end;
$fn$;

-- 'reference' when the only phone rule is a bare 10+ digit run (a UTR, PNR or
-- order id, blocked by policy; the copy points to Help), 'date_like' when it is
-- only the every-digit-joined reading. Null otherwise.
create or replace function private.contact_guard_reason(p_rules text[])
returns text
language sql
immutable
strict
parallel safe
as $fn$
  select case
    when private.contact_guard_category(p_rules) is distinct from 'phone' then null
    when (select array_agg(x order by x) from unnest(p_rules) x
          where x = any(array[${PHONE_IDS.map(sqlLit).join(
            ', ',
          )}]::text[])) = array['phone_run10']::text[] then 'reference'
    when (select array_agg(x order by x) from unnest(p_rules) x
          where x = any(array[${PHONE_IDS.map(sqlLit).join(
            ', ',
          )}]::text[])) = array['phone_digits']::text[] then 'date_like'
  end;
$fn$;

-- A message that is only digit groups (after carrier words and symbols go)
-- returns its digits; any other message returns ''.
create or replace function private.contact_guard_fragment(p_text text)
returns text
language plpgsql
immutable
strict
parallel safe
as $fn$
declare
  v text;
begin
${sqlFragmentCopies}
${fragmentSteps}
  if v !~ ${sqlLit(spec.FRAGMENT.shape)} then
    return '';
  end if;
  v := regexp_replace(v, '[^0-9]', '', 'g');
  if length(v) < ${spec.FRAGMENT.minDigits} then
    return '';
  end if;
  return v;
end;
$fn$;

-- A message with no run of two or more digits: the window steps over it.
create or replace function private.contact_guard_is_chatter(p_text text)
returns boolean
language plpgsql
immutable
strict
parallel safe
as $fn$
declare
  v text;
begin
${sqlFragmentCopies}
  return v ~ ${sqlLit(spec.FRAGMENT.chatter)};
end;
$fn$;

-- p_texts is the sender's recent messages oldest first, the new one last.
-- Joins every run of two or more fragments that ends at the new message, in
-- sending order and reversed, and returns the first join that is a mobile.
-- Null when none is: the new message alone never counts here, the hard rules
-- already judged it.
create or replace function private.contact_guard_window(p_texts text[])
returns text
language plpgsql
immutable
strict
parallel safe
as $fn$
declare
  v_n   integer := coalesce(cardinality(p_texts), 0);
  v_fwd text;
  v_rev text;
  v_pay text;
begin
  if v_n < 2 then
    return null;
  end if;
  v_fwd := private.contact_guard_fragment(coalesce(p_texts[v_n], ''));
  if v_fwd = '' then
    return null;
  end if;
  v_rev := v_fwd;
  for i in reverse v_n - 1 .. 1 loop
    v_pay := private.contact_guard_fragment(coalesce(p_texts[i], ''));
    if v_pay = '' then
      -- Chatter (no digit run of two or more) is stepped over; anything else
      -- with digits ends the run.
      exit when not private.contact_guard_is_chatter(coalesce(p_texts[i], ''));
      continue;
    end if;
    v_fwd := v_pay || v_fwd;
    v_rev := v_rev || v_pay;
    exit when length(v_fwd) > 13;
    if v_fwd ~ ${sqlLit(spec.FRAGMENT.mobile)} then
      return v_fwd;
    end if;
    if v_rev ~ ${sqlLit(spec.FRAGMENT.mobile)} then
      return v_rev;
    end if;
  end loop;
  return null;
end;
$fn$;

-- Every working copy, for parity tests and moderation.
create or replace function private.contact_guard_copies(p_text text)
returns jsonb
language plpgsql
immutable
strict
parallel safe
as $fn$
declare
${sqlDeclareCopies}
begin
${sqlAllCopies}
  return jsonb_build_object(${COPY_NAMES.map(n => `${sqlLit(n)}, v_${n}`).join(
    ', ',
  )});
end;
$fn$;

create or replace function private.contact_guard_spec_version()
returns text
language sql
immutable
parallel safe
as $fn$
  select ${sqlLit(SPEC_SHA)}::text;
$fn$;

do $grants$
declare
  v_fn regprocedure;
begin
  for v_fn in
    select p.oid::regprocedure
    from pg_proc p
    where p.pronamespace = 'private'::regnamespace
      and (p.proname like 'cg\\_copy\\_%' or p.proname like 'contact\\_guard\\_%')
      and p.proname not in ('contact_guard_gate', 'contact_guard_log', 'contact_guard_mode', 'contact_guard_purge')
  loop
    execute format('revoke all on function %s from public, anon, authenticated', v_fn);
    execute format('grant execute on function %s to service_role', v_fn);
  end loop;
end;
$grants$;
`;

// --- TypeScript ---------------------------------------------------------------
const jsCopyFns = spec.COPIES.map(copy => {
  const body = copy.steps.map(step => `  ${emitOp(step, jsCtx).js}`).join('\n');
  return `function copy_${copy.name}(p: string): string {
  let v = p;
${body}
  return v;
}`;
});
const jsFragmentSteps = spec.FRAGMENT.steps
  .map(step => `  ${emitOp(step, jsCtx).js}`)
  .join('\n');
const jsBlockedRe = spec.COPIES.map(c => {
  const rules = hardByCopy(c.name);
  return rules.length > 0 ? [c.name, jsCtx.re(combined(rules), 'u')] : null;
}).filter(Boolean);
const jsPrefilter = jsCtx.re(spec.PREFILTER.re, 'u');
const jsRuleTests = spec.HARD.map(rule => {
  const cond = rule.requires
    ? `${jsCtx.re(rule.re, 'u')}.test(c.${rule.copy}) && ${jsCtx.re(
        rule.requires.re,
        'u',
      )}.test(c.${rule.requires.copy})`
    : `${jsCtx.re(rule.re, 'u')}.test(c.${rule.copy})`;
  return `  if (!ids.includes(${JSON.stringify(
    rule.id,
  )}) && ${cond}) {\n    ids.push(${JSON.stringify(rule.id)});\n  }`;
}).join('\n');
const jsShape = jsCtx.re(spec.FRAGMENT.shape, 'u');
const jsMobile = jsCtx.re(spec.FRAGMENT.mobile, 'u');
const jsChatter = jsCtx.re(spec.FRAGMENT.chatter, 'u');
const jsNonDigit = jsCtx.re('[^0-9]', 'gu');
const copyCalls = spec.COPIES.map(
  c =>
    `  const ${c.name} = copy_${c.name}(${
      c.from === 'input' ? 'text' : c.from
    });`,
).join('\n');
const jsFragmentCopies = phoneCopyPath
  .map(c => `  v = copy_${c.name}(${c.from === 'input' ? 'text' : 'v'});`)
  .join('\n');

const ts = `/**
 * GENERATED FILE, DO NOT EDIT.
 *
 * Source: design/contact-guard.spec.mjs and design/contact-guard.tables.json,
 * through scripts/gen-contact-guard.mjs. Regenerate with \`npm run
 * contact-guard\`; \`npm run contact-guard:check\` fails on drift.
 *
 * The app's mirror of the contact guard's HARD tier. The server decides
 * (${spec.MIGRATION.replace(
   'supabase/migrations/',
   '',
 )}, schema private); this only predicts, so the
 * composer can explain a block before the send. Signal rules are server only.
 * If this engine rejects any pattern, every function reports "not blocked" and
 * the server's answer is the only one: a broken mirror must never block.
 */


export const CONTACT_GUARD_SPEC = ${JSON.stringify(SPEC_SHA)};

export type ContactCategory = ${spec.CATEGORY_ORDER.map(c =>
  JSON.stringify(c),
).join(' | ')};

const SOURCES: ReadonlyArray<readonly [string, string]> = [
${jsRegexes
  .map(r => `  [${jsStr(r.source)}, ${JSON.stringify(r.flags)}],`)
  .join('\n')}
];

/** Whether any code unit is outside ASCII; the SQL asks v ~ '[^\\u0001-\\u007f]'. */
function hasNonAscii(v: string): boolean {
  for (let i = 0; i < v.length; i += 1) {
    if (v.charCodeAt(i) > 0x7f) {
      return true;
    }
  }
  return false;
}

let compiled: RegExp[] | null | undefined;

/** Compiles every pattern once. Null when this engine rejects one. */
function regexes(): RegExp[] | null {
  if (compiled === undefined) {
    try {
      compiled = SOURCES.map(([source, flags]) => new RegExp(source, flags));
    } catch {
      compiled = null;
    }
  }
  return compiled;
}

let R: RegExp[] = [];

/** The compiled pattern at \`i\`. Only reached after ready() succeeded. */
function re(i: number): RegExp {
  return R[i] as RegExp;
}

const FOLD_FROM = ${jsStr(tables.fold.from)};
const FOLD_TO = ${jsStr(tables.fold.to)};

let fold: Map<string, string> | undefined;
function foldMap(): Map<string, string> {
  if (fold === undefined) {
    const from = Array.from(FOLD_FROM);
    const to = Array.from(FOLD_TO);
    fold = new Map(from.map((ch, i) => [ch, to[i] ?? ch]));
  }
  return fold;
}

${jsTmaps
  .map(
    (t, i) => `let tm${i}: Map<string, string> | undefined;
function tmap${i}(): Map<string, string> {
  if (tm${i} === undefined) {
    const from = Array.from(${jsStr(t.from)});
    const to = Array.from(${jsStr(t.to)});
    tm${i} = new Map(from.map((ch, i2) => [ch, to[i2] ?? ch]));
  }
  return tm${i};
}`,
  )
  .join('\n\n')}

${jsDicts
  .map(
    (d, i) => `const DICT${i}: Record<string, string> = ${jsStr(d)};
let d${i}: Map<string, string> | undefined;
function dict${i}(): Map<string, string> {
  if (d${i} === undefined) {
    d${i} = new Map(Object.entries(DICT${i}));
  }
  return d${i};
}`,
  )
  .join('\n\n')}

/** Postgres translate(): each character of \`map\`'s keys becomes its value. */
function translate(v: string, map: Map<string, string>): string {
  let out = '';
  for (const ch of v) {
    out += map.get(ch) ?? ch;
  }
  return out;
}

${jsCopyFns.join('\n\n')}

type Copies = { ${COPY_NAMES.map(n => `${n}: string`).join('; ')} };

function ready(): boolean {
  const all = regexes();
  if (all === null) {
    return false;
  }
  R = all;
  return true;
}

/** Every working copy of the text, for tests and debugging. */
export function contactGuardCopies(text: string): Copies | null {
  if (!ready()) {
    return null;
  }
${copyCalls}
  return { ${COPY_NAMES.join(', ')} };
}

/** True when any hard rule fires: the server would refuse this in enforce mode. */
export function isContactBlocked(text: string): boolean {
  if (!ready()) {
    return false;
  }
  const t = copy_t(text);
  if (!${jsPrefilter}.test(t)) {
    return false;
  }
  const c: Partial<Copies> = { t };
${spec.COPIES.filter(cp => cp.name !== 't')
  .map(
    cp =>
      `  c.${cp.name} = copy_${cp.name}(c.${
        cp.from === 'input' ? 't' : cp.from
      } as string);`,
  )
  .join('\n')}
${jsBlockedRe
  .map(
    ([name, re]) =>
      `  if (${re}.test(c.${name} as string)) {\n    return true;\n  }`,
  )
  .join('\n')}
${spec.HARD.filter(r => r.requires)
  .map(
    r =>
      `  if (${jsCtx.re(r.re, 'u')}.test(c.${r.copy} as string) && ${jsCtx.re(
        r.requires.re,
        'u',
      )}.test(c.${r.requires.copy} as string)) {\n    return true;\n  }`,
  )
  .join('\n')}
  return false;
}

/** The hard rule ids that fire, in spec order. */
export function contactGuardRules(text: string): string[] {
  if (!ready() || !${jsPrefilter}.test(copy_t(text))) {
    return [];
  }
  return contactGuardRulesUnfiltered(text);
}

/** Whether the fast path's prefilter lets the text through to the rules. */
export function contactGuardPrefilter(text: string): boolean {
  return ready() && ${jsPrefilter}.test(copy_t(text));
}

/**
 * Every hard rule, without the prefilter. Tests use it to prove the
 * prefilter never hides a hit; nothing else should.
 */
export function contactGuardRulesUnfiltered(text: string): string[] {
  const ids: string[] = [];
  if (!ready()) {
    return ids;
  }
  const c = contactGuardCopies(text) as Copies;
${jsRuleTests}
  return ids;
}

const CATEGORY_OF: Record<string, ContactCategory> = ${JSON.stringify(
  CATEGORY_OF,
)};
const CATEGORY_ORDER: ContactCategory[] = ${JSON.stringify(
  spec.CATEGORY_ORDER,
)};
const PHONE_IDS = ${JSON.stringify(PHONE_IDS)};

/** The category the UI names, by priority; null when nothing fired. */
export function contactCategory(rules: readonly string[]): ContactCategory | null {
  for (const category of CATEGORY_ORDER) {
    if (rules.some(id => CATEGORY_OF[id] === category)) {
      return category;
    }
  }
  return null;
}

/** 'reference' for a bare 10+ digit run alone, 'date_like' for the joined-digits reading alone. */
export function contactReason(rules: readonly string[]): 'reference' | 'date_like' | null {
  if (contactCategory(rules) !== 'phone') {
    return null;
  }
  const phone = rules.filter(id => PHONE_IDS.includes(id));
  if (phone.length === 1 && phone[0] === 'phone_run10') {
    return 'reference';
  }
  if (phone.length === 1 && phone[0] === 'phone_digits') {
    return 'date_like';
  }
  return null;
}

/** A message that is only digit groups returns its digits; any other returns ''. */
export function contactFragment(text: string): string {
  if (!ready()) {
    return '';
  }
  let v = text;
${jsFragmentCopies}
${jsFragmentSteps}
  if (!${jsShape}.test(v)) {
    return '';
  }
  v = v.replace(${jsNonDigit}, '');
  return v.length < ${spec.FRAGMENT.minDigits} ? '' : v;
}

/** A message with no run of two or more digits: the window steps over it. */
export function contactChatter(text: string): boolean {
  if (!ready()) {
    return false;
  }
  let v = text;
${jsFragmentCopies}
  return ${jsChatter}.test(v);
}

/**
 * The sender's recent messages oldest first, the new one last. Returns the
 * mobile a run of fragments ending at the new message joins into (in sending
 * order or reversed), or null.
 */
export function contactWindow(texts: readonly string[]): string | null {
  const n = texts.length;
  if (n < 2) {
    return null;
  }
  let fwd = contactFragment(texts[n - 1] ?? '');
  if (fwd === '') {
    return null;
  }
  let rev = fwd;
  for (let i = n - 2; i >= 0; i -= 1) {
    const pay = contactFragment(texts[i] ?? '');
    if (pay === '') {
      if (!contactChatter(texts[i] ?? '')) {
        break;
      }
      continue;
    }
    fwd = pay + fwd;
    rev = rev + pay;
    if (fwd.length > 13) {
      break;
    }
    if (${jsMobile}.test(fwd)) {
      return fwd;
    }
    if (${jsMobile}.test(rev)) {
      return rev;
    }
  }
  return null;
}
`;

// --- Write or check ---------------------------------------------------------
const MIGRATION_PATH = join(ROOT, spec.MIGRATION);
// The repo never spells one messenger's name in code (see the spec's TG).
// Every place it reaches an output is a pattern, where both engines read
// g as "g": one backslash in SQL (standard_conforming_strings), two in
// a TypeScript string literal.
const NAME = new RegExp(['tele', 'gram'].join(''), 'gi');
const scrub = (text, backslash) =>
  text.replace(NAME, m => `${m.slice(0, 4)}${backslash}u0067${m.slice(5)}`);
const outputs = [
  [TS_PATH, scrub(ts, '\\\\')],
  [MIGRATION_PATH, scrub(sql, '\\')],
];
for (const [path, content] of outputs) {
  if (NAME.test(content)) {
    console.error(
      `${LABEL} FAILED: ${path.replace(
        ROOT,
        '',
      )} would spell the messenger's name`,
    );
    process.exit(1);
  }
}

if (CHECK) {
  for (const [path, content] of outputs) {
    let current = '';
    try {
      current = readFileSync(path, 'utf8');
    } catch {
      console.error(
        `${LABEL} FAILED, ${path.replace(
          ROOT,
          '',
        )} does not exist. Run \`npm run contact-guard\`.`,
      );
      process.exit(1);
    }
    if (current !== content) {
      console.error(
        `${LABEL} FAILED, ${path.replace(
          ROOT,
          '',
        )} is stale. Run \`npm run contact-guard\`.`,
      );
      process.exit(1);
    }
  }
} else {
  for (const [path, content] of outputs) {
    writeFileSync(path, content);
  }
}

console.log(
  `${LABEL} OK\n  spec ${SPEC_SHA.slice(0, 8)}: ${
    HARD_IDS.length
  } hard rules, ${spec.SIGNAL.length} signal rules, ` +
    `${spec.COPIES.length} copies, ${jsRegexes.length} mirror patterns`,
);
